/*
 Problem: 4043. Count Rotations With Exactly K Equal Adjacent Pairs
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 9.5 MB (59.03%)
 Tags: String, Sliding Window, Enumeration
*/
class Solution {
public:
    int countRotations(string s, int k) {
        int n = s.size(), base = 0;

        for (int i = 0; i + 1 < n; ++i)
            base += s[i] == s[i + 1];

        int ans = 0, add = s[0] == s[n - 1];

        for (int p = 0; p < n; ++p) {
            int score = p ? base - (s[p - 1] == s[p]) + add : base;
            ans += score == k;
        }

        return ans;
    }
};
